{"command": "python -c "
import json

with open('sales_data.json') as f:
    sales = json.load(f)

with open('adjustments.json') as f:
    adjustments = json.load(f)

adj_dict = {}
for adj in adjustments:
    adj_dict[adj['order_id']] = adj

# 按品类汇总
category_totals = {}
for sale in sales:
    category = sale['category']
    if category not in category_totals:
        category_totals[category] = {'net': 0.0, 'orders': []}

    order_id = sale['order_id']
    original = sale['quantity'] * sale['unit_price']
    adjusted = original

    if order_id in adj_dict:
        adj = adj_dict[order_id]
        if adj['type'] == 'partial_refund':
            adjusted += adj['amount_delta']
        elif adj['type'] == 'cancelled':
            adjusted = 0

    category_totals[category]['net'] += adjusted
    if adjusted > 0:
        category_totals[category]['orders'].append(order_id)

print('各品类净销售额:')
for cat, data in sorted(category_totals.items(), key=lambda x: (-x[1]['net'], x[0])):
    print('{}: {:.2f} (有效订单: {})'.format(cat, data['net'], len(data['orders'])))
""}
